const STORAGE_KEY = 'gravity-ui-theme';

function readStoredTheme(): Theme {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw === 'light' || raw === 'dark' || raw === 'light-hc' || raw === 'dark-hc' || raw === 'system') {
      return raw;
    }
  } catch {}
